<?php
namespace Tests\Feature;
use App\Models\{Category,OrderRequest,Product,ProductVariant}; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Facades\Mail; use Tests\TestCase;
class OrderRequestTest extends TestCase { use RefreshDatabase;
 public function test_cart_accepts_variants_and_creates_non_binding_order():void { Mail::fake(); $c=Category::create(['name'=>'Solar','slug'=>'solar']); $p=Product::create(['category_id'=>$c->id,'name'=>'Painel','slug'=>'painel','is_published'=>true]); $v=ProductVariant::create(['product_id'=>$p->id,'name'=>'715 W','is_available'=>true]); $this->post('/pedido/adicionar/painel',['variant_id'=>$v->id,'quantity'=>2])->assertSessionHas('success'); $this->get('/pedido')->assertOk()->assertSee('715 W')->assertSee('Não existe pagamento'); $this->post('/pedido/confirmar',['customer_type'=>'professional','name'=>'Cliente','email'=>'cliente@example.com','phone'=>'960000000','region'=>'Madeira','fulfilment_type'=>'both','terms'=>'1'])->assertRedirect(); $this->assertDatabaseHas('order_requests',['customer_type'=>'professional','region'=>'Madeira','status'=>'new']); $this->assertDatabaseHas('order_request_items',['product_name'=>'Painel','variant_name'=>'715 W','quantity'=>2]); }
 public function test_order_requires_confirmation_consent():void { $c=Category::create(['name'=>'Solar','slug'=>'solar']); $p=Product::create(['category_id'=>$c->id,'name'=>'Painel','slug'=>'painel','is_published'=>true]); $this->withSession(['order_cart'=>[$p->id.':0'=>['product_id'=>$p->id,'variant_id'=>null,'quantity'=>1]]])->post('/pedido/confirmar',['customer_type'=>'private','name'=>'Cliente','email'=>'cliente@example.com','phone'=>'960000000','region'=>'Açores','fulfilment_type'=>'delivery'])->assertSessionHasErrors('terms'); $this->assertSame(0,OrderRequest::count()); }
 public function test_homepage_is_independent_from_catalog_content():void { $this->get('/')->assertOk()->assertSee('Soluções integradas para viver e trabalhar melhor')->assertSee('Açores + Madeira')->assertDontSee('Produto Tropikal · Série Eco'); }
}
